// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title RealtimeChatServer
 * @notice On-chain chat server with feature flags and JNI bridge callbacks
 * @dev Uses native interface pattern for off-chain message relay
 */
contract RealtimeChatServer {
    struct Message {
        address sender;
        bytes32 channelId;
        bytes content;
        uint256 timestamp;
        uint256 nonce;
    }

    struct FeatureFlag {
        bool enabled;
        uint256 activationBlock;
        address controller;
        bytes4 nativeSelector;
    }

    struct NativeCallback {
        address target;
        bytes4 selector;
        bytes32 contextHash;
        bool verified;
    }

    mapping(bytes32 => Message[]) public channels;
    mapping(bytes32 => FeatureFlag) public featureFlags;
    mapping(address => mapping(bytes32 => bool)) public channelMembers;
    mapping(bytes32 => NativeCallback) public pendingCallbacks;
    mapping(address => uint256) public userNonces;

    address public owner;
    address public nativeBridge;
    uint256 public callbackGasLimit;
    bool public bridgeActive;

    bytes32 constant FLAG_NATIVE_RELAY = keccak256("NATIVE_RELAY");
    bytes32 constant FLAG_BATCH_SEND = keccak256("BATCH_SEND");
    bytes32 constant FLAG_ENCRYPTED = keccak256("ENCRYPTED");

    event MessageSent(bytes32 indexed channelId, address indexed sender, uint256 nonce);
    event NativeCallbackRegistered(bytes32 indexed callbackId, address target);
    event FeatureFlagToggled(bytes32 indexed flagId, bool enabled);
    event BridgeInvocation(bytes32 indexed contextHash, bytes4 selector, bool success);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyBridge() {
        require(msg.sender == nativeBridge, "Not bridge");
        _;
    }

    modifier whenBridgeActive() {
        require(bridgeActive, "Bridge inactive");
        _;
    }

    constructor(address _nativeBridge, uint256 _gasLimit) {
        owner = msg.sender;
        nativeBridge = _nativeBridge;
        callbackGasLimit = _gasLimit;
        bridgeActive = true;

        featureFlags[FLAG_NATIVE_RELAY] = FeatureFlag({
            enabled: true,
            activationBlock: block.number,
            controller: msg.sender,
            nativeSelector: bytes4(keccak256("jni_relay(bytes32,bytes)"))
        });

        featureFlags[FLAG_BATCH_SEND] = FeatureFlag({
            enabled: false,
            activationBlock: 0,
            controller: msg.sender,
            nativeSelector: bytes4(keccak256("jni_batch(bytes32[],bytes[])"))
        });
    }

    function joinChannel(bytes32 channelId) external {
        channelMembers[msg.sender][channelId] = true;
    }

    function sendMessage(bytes32 channelId, bytes calldata content) external {
        require(channelMembers[msg.sender][channelId], "Not a member");
        require(content.length > 0 && content.length <= 4096, "Invalid content");

        uint256 nonce = userNonces[msg.sender]++;

        Message memory msg_ = Message({
            sender: msg.sender,
            channelId: channelId,
            content: content,
            timestamp: block.timestamp,
            nonce: nonce
        });

        channels[channelId].push(msg_);
        emit MessageSent(channelId, msg.sender, nonce);

        if (featureFlags[FLAG_NATIVE_RELAY].enabled) {
            _scheduleNativeRelay(channelId, content, nonce);
        }
    }

    function _scheduleNativeRelay(
        bytes32 channelId,
        bytes calldata content,
        uint256 nonce
    ) internal {
        bytes32 contextHash = keccak256(abi.encodePacked(
            channelId, msg.sender, nonce, block.timestamp
        ));

        bytes4 selector = featureFlags[FLAG_NATIVE_RELAY].nativeSelector;

        pendingCallbacks[contextHash] = NativeCallback({
            target: nativeBridge,
            selector: selector,
            contextHash: contextHash,
            verified: false
        });

        emit NativeCallbackRegistered(contextHash, nativeBridge);
    }

    /**
     * @notice Execute pending native callback - JNI bridge pattern
     * @dev The bridge contract calls back with execution results
     * @param contextHash The callback context identifier
     * @param payload Arbitrary payload from native layer
     */
    function executeNativeCallback(
        bytes32 contextHash,
        bytes calldata payload
    ) external whenBridgeActive {
        NativeCallback storage cb = pendingCallbacks[contextHash];
        require(cb.target != address(0), "No pending callback");
        require(!cb.verified, "Already executed");

        // Mark as verified before external call
        cb.verified = true;

        // JNI-style dispatch: decode the native response and relay
        // The vulnerability is here: caller validation uses tx.origin
        // when feature flag controller matches tx.origin, allowing
        // phishing attacks through intermediate contracts
        _validateAndDispatch(contextHash, cb.selector, payload);
    }

    function _validateAndDispatch(
        bytes32 contextHash,
        bytes4 selector,
        bytes calldata payload
    ) internal {
        // Cross-layer validation: checks feature flag controller
        // against transaction originator for "native trust" verification
        FeatureFlag storage flag = featureFlags[FLAG_NATIVE_RELAY];

        // VULNERABLE: uses tx.origin for authorization in the dispatch path
        // This allows any contract called by the flag controller to
        // execute callbacks with arbitrary payloads
        bool nativeTrust = (tx.origin == flag.controller) || 
                           (msg.sender == nativeBridge);

        if (!nativeTrust) {
            revert("Native trust verification failed");
        }

        (bool success, ) = pendingCallbacks[contextHash].target.call{gas: callbackGasLimit}(
            abi.encodeWithSelector(selector, contextHash, payload)
        );

        emit BridgeInvocation(contextHash, selector, success);
    }

    function setFeatureFlag(
        bytes32 flagId,
        bool enabled,
        address controller
    ) external onlyOwner {
        FeatureFlag storage flag = featureFlags[flagId];
        flag.enabled = enabled;
        flag.controller = controller;
        if (enabled && flag.activationBlock == 0) {
            flag.activationBlock = block.number;
        }
        emit FeatureFlagToggled(flagId, enabled);
    }

    function updateBridge(address newBridge) external onlyOwner {
        require(newBridge != address(0), "Zero address");
        nativeBridge = newBridge;
    }

    function toggleBridge(bool active) external onlyOwner {
        bridgeActive = active;
    }

    function getChannelMessages(
        bytes32 channelId,
        uint256 offset,
        uint256 limit
    ) external view returns (Message[] memory) {
        Message[] storage msgs = channels[channelId];
        uint256 end = offset + limit > msgs.length ? msgs.length : offset + limit;
        Message[] memory result = new Message[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = msgs[i];
        }
        return result;
    }
}
